<?php defined('BASEPATH') OR exit('No direct script access allowed');class Reviews extends MY_Controller{function __construct(){parent::__construct();$this->load->model('Review_model','reviews');}function index(){if($this->input->method(TRUE)==='GET')return $this->respond($this->reviews->dashboard());if(!$c=$this->require_auth())return;$d=$this->body();if(!$this->valid($d))return;$u=$this->db->where('id',$c['sub'])->get('users')->row_array();return $this->respond($this->reviews->save($c['sub'],$u['username']?:$u['display_name']?:'Verified customer',$d),201);}function published($id){$r=$this->reviews->one($id,TRUE);return $r?$this->respond($r):$this->fail('NOT_FOUND','Review not found',404);}function me(){if(!$c=$this->require_auth())return;if($this->input->method(TRUE)==='GET')return $this->respond($this->reviews->mine($c['sub']));if($this->input->method(TRUE)==='DELETE'){if($this->reviews->remove_mine($c['sub'])){$this->output->set_status_header(204);return;}return $this->fail('NOT_FOUND','Review not found',404);}$d=$this->body();if(!$this->valid($d))return;$u=$this->db->where('id',$c['sub'])->get('users')->row_array();return $this->respond($this->reviews->save($c['sub'],$u['username']?:$u['display_name']?:'Verified customer',$d));}function admin($id=NULL){if(!$c=$this->require_auth())return;$this->load->model('Admin_model','admin');if(!$this->admin->access($c['sub'],$c['organizationId']??NULL))return $this->fail('FORBIDDEN','Administrator access required',403);if($id){$status=$this->body()['status']??'';if(!in_array($status,array('published','hidden'),TRUE))return $this->fail('VALIDATION_ERROR','Invalid status',422);$r=$this->reviews->status($id,$status);return $r?$this->respond($r):$this->fail('NOT_FOUND','Review not found',404);}$all=$this->reviews->all();$published=array_filter($all,function($r){return$r['status']==='published';});$sum=array_sum(array_column($published,'rating'));return $this->respond(array('totalAll'=>count($all),'totalPublished'=>count($published),'hidden'=>count($all)-count($published),'averageRating'=>count($published)?round($sum/count($published),1):0,'reviews'=>$all));}private function valid($d){if(!isset($d['rating'])||$d['rating']<1||$d['rating']>5||trim($d['content']??'')===''||strlen($d['content'])>4000||strlen($d['title']??'')>120){$this->fail('VALIDATION_ERROR','Invalid review',422);return FALSE;}return TRUE;}}
